testcase.name:
Máquina de estados de la búsqueda > no encontrado lleva al estado () => __vite_ssr_import_0__.vi.mocked(__vi_import_2__.consultarCodigoBarras).mockResolvedValue({
				...ENCONTRADO,
				encontrado: false,
				producto: null
			})

Máquina de estados de la búsqueda > 409 lleva al estado () => __vite_ssr_import_0__.vi.mocked(__vi_import_2__.consultarCodigoBarras).mockRejectedValue(new __vi_import_3__.ApiError("Ya existe", 409, {}, {
				mensaje: "Ya existe",
				insumo_id: 10,
				activo: false
			}))
